# Decimal commas are used in the Russian-facing prose; answer keys stay machine-readable.
import re
for q in questions:
    for field in ('prompt','explanation'):q[field]=re.sub(r'(?<=\d)\.(?=\d)', ',', q[field])

# Move answer positions deterministically; correct choices are not always first.
import random
for q in questions:
    if q['kind']=='choice':
        correct=next(option for option in q['options'] if option['id']==q['answer'])
        random.Random(q['id']).shuffle(q['options'])
        for i,option in enumerate(q['options']):
            if option is correct:q['answer']=str(i+1)
            option['id']=str(i+1)
assert len(topics)==47 and len(questions)==150
assert len({q['id'] for q in questions})==len(questions)
for t in topics:
    assert sum(q['subject_code']==t['subject_code'] and q['task_number']==t['task_number'] for q in questions)>=3
    t['theory']+='\n\n📌 Об источниках\nЭто авторский учебный конспект по теме задания, а не текст официальной демоверсии. Нумерация сверена с проектом ФИПИ-2027. Ссылка ведёт на официальный материал; базовые тематические памятки навигатора пока опубликованы за 2026 год.'
meta=dict(version='ege-2027-20261025-v1',exam_year=2027,status='Проект ФИПИ-2027',checked_at='2026-10-25',format_source=DEMO,navigator_source=NAV,notice='Нумерация — по проектам ФИПИ-2027. Конспекты и мини-задания учебные, не являются официальными КИМ. Развёрнутые ответы требуют проверки полного решения преподавателем.')
Path('data/ege_2027.json').write_text(json.dumps(dict(**meta,topics=topics),ensure_ascii=False,indent=2)+'\n')
Path('data/practice_2027.json').write_text(json.dumps(dict(version=meta['version'],questions=questions),ensure_ascii=False,indent=2)+'\n')
print(f'Built {len(topics)} topics and {len(questions)} original practice items')
